`timescale 1ns/1ps
// RAM download slot S3. 1..128 steps; 3-bit note C4..C5, beats 1..3.
// No nonvolatile storage: content is lost on FPGA reset/power down.
// ACK is generated by the host protocol only after the associated pulse.
module song_ram_v87(
 input wire clk,rst_n,clear_upload,append_step,commit,
 input wire [2:0] new_note,input wire [1:0] new_beats,
 input wire [7:0] read_index,
 output wire [2:0] read_note,output wire [1:0] read_beats,
 output reg [7:0] song_length,
 output reg ready,
 output wire can_append,can_commit
);
 reg [4:0] ram [0:127];
 reg [7:0] write_count;
 assign can_append = !ready && write_count<8'd128;
 assign can_commit = !ready && write_count!=8'd0;
 wire [4:0] raw_data=ram[read_index[6:0]];
 assign read_note=(ready && read_index<song_length)?raw_data[2:0]:3'd0;
 assign read_beats=(ready && read_index<song_length)?raw_data[4:3]:2'd1;
 always @(posedge clk or negedge rst_n)begin
  if(!rst_n)begin write_count<=0;song_length<=0;ready<=0;end
  else if(clear_upload)begin write_count<=0;song_length<=0;ready<=0;end
  else if(append_step && can_append)begin
      ram[write_count[6:0]]<={new_beats,new_note};
      write_count<=write_count+8'd1;
  end else if(commit && can_commit)begin
      song_length<=write_count;
      ready<=1;
  end
 end
endmodule
